import fs from 'node:fs';import path from 'node:path';import zlib from 'node:zlib';
const data=JSON.parse(zlib.gunzipSync(fs.readFileSync('copy-update.json.gz')));
for(const [rel,contents] of Object.entries(data.pages)){const f=path.join('public',rel);if(!fs.existsSync(f))throw Error('Missing existing page '+f);fs.writeFileSync(f,contents);}
let footers=0;
function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else if(/\.(html|js)$/.test(f)){let s=fs.readFileSync(f,'utf8');if(s.includes(data.footer.old)){s=s.replaceAll(data.footer.old,data.footer.new);fs.writeFileSync(f,s);footers++;}}}}
walk('public');console.log('Copy review applied to '+Object.keys(data.pages).length+' pages; shared footer updated in '+footers+' further files.');
// Reuse the corrected vertical-cylinder concept from the Industries directory.
const alt='Hydroelectric gate concept with a vertical hydraulic cylinder mounted above the gate on a fixed steel yoke';
const tag=[...data.pages['industries/index.html'].matchAll(/<img\b[^>]*>/g)].map(m=>m[0]).find(t=>t.includes('alt="'+alt+'"'));
if(!tag)throw Error('Missing corrected hydroelectric directory image');
const src=tag.match(/src="([^"]+)"/)[1];if(!src.startsWith('data:image/jpeg;base64,'))throw Error('Unexpected reference image');
const dest='public/industries/water-hydraulics-for-hydroelectric-power/index.html';let html=fs.readFileSync(dest,'utf8');
const old='src="/assets/industries-20261008/hydro-concept.webp"';if(html.split(old).length!==2)throw Error('Expected exactly one hydroelectric hero');
html=html.replace(old,'src="'+src+'"').replace('alt="Illustrative intake isolation gate concept for hydroelectric power"','alt="'+alt+'"');fs.writeFileSync(dest,html);console.log('Vertical-cylinder hero applied.');

// Industry editorial revision. Apply only to the exact reviewed page versions.
import { createHash } from 'node:crypto';
const industryRevision=JSON.parse(zlib.gunzipSync(fs.readFileSync('industry-edits.json.gz')));
const digest=value=>createHash('sha256').update(value).digest('hex');
for(const [relative,change] of Object.entries(industryRevision)){
 const file=path.join('public',relative);let value=fs.readFileSync(file,'utf8');
 if(digest(value)!==change.before)throw Error('Industry baseline changed: '+relative);
 for(const edit of [...change.edits].reverse())value=value.slice(0,edit.start)+edit.text+value.slice(edit.end);
 if(digest(value)!==change.after)throw Error('Industry output mismatch: '+relative);
 fs.writeFileSync(file,value);
}
console.log('Industry editorial revision verified and applied to '+Object.keys(industryRevision).length+' pages.');

// Three-medium comparisons, guarded against changes to the reviewed editorial release.
const mediumTables=JSON.parse(zlib.gunzipSync(fs.readFileSync('industry-comparison-tables.json.gz')));
for(const [relative,change] of Object.entries(mediumTables)){
 const file=path.join('public',relative);let value=fs.readFileSync(file,'utf8');
 if(digest(value)!==change.before)throw Error('Comparison baseline changed: '+relative);
 for(const edit of [...change.edits].reverse())value=value.slice(0,edit.start)+edit.text+value.slice(edit.end);
 if(digest(value)!==change.after)throw Error('Comparison output mismatch: '+relative);
 fs.writeFileSync(file,value);
}
console.log('Three-medium comparison tables verified on '+Object.keys(mediumTables).length+' industry pages.');

// Approved customer-first site copy; retain all earlier release transformations.
const siteTone=JSON.parse(zlib.gunzipSync(fs.readFileSync('site-tone.json.gz')));
for(const [relative,change] of Object.entries(siteTone)){
 const file=path.join('public',relative);let value=fs.readFileSync(file,'utf8');
 if(digest(value)!==change.before)throw Error('Site tone baseline changed: '+relative);
 let chars=Array.from(value);for(const edit of [...change.edits].reverse())chars=chars.slice(0,edit.start).concat(Array.from(edit.text),chars.slice(edit.end));value=chars.join('');
 if(digest(value)!==change.after)throw Error('Site tone output mismatch: '+relative);
 fs.writeFileSync(file,value);
}
console.log('Approved site tone verified on '+Object.keys(siteTone).length+' pages.');

